-- Parity test for Cognos report Seasonal_Consumption_Trends (cluster BIL_017, 3 runs/day)
-- Generated by SemanticLift 1.0.0; tolerance +/-0.5% on totals
-- Measures whose numbers are expected to change (F6 aggregation correction): max_peak_demand_kw
WITH cognos AS (
    SELECT dt.FISCAL_YEAR AS fiscal_year, dt.MONTH_NAME AS month_name, dt.QUARTER AS quarter, customer.ACCOUNT_TYPE AS account_type, customer.CUSTOMER_SEGMENT AS customer_segment, location.CITY AS city, location.REGION AS region, SUM(meter_reading.CONSUMPTION_KWH) AS total_consumption_kwh, SUM(meter_reading.PEAK_DEMAND_KW) AS max_peak_demand_kw
    FROM CORE.FCT_METER_READING meter_reading
    JOIN CORE.DIM_DATE dt ON meter_reading.DATE_KEY = dt.DATE_KEY
    JOIN CORE.DIM_METER meter ON meter_reading.METER_ID = meter.METER_ID
    JOIN CORE.DIM_CUSTOMER customer ON meter.CUSTOMER_ID = customer.CUSTOMER_ID
    JOIN CORE.DIM_LOCATION location ON meter.LOCATION_ID = location.LOCATION_ID
    WHERE dt.FISCAL_YEAR = 2026
    GROUP BY 1, 2, 3, 4, 5, 6, 7
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_METER_CONSUMPTION
        DIMENSIONS dt.fiscal_year, dt.month_name, dt.quarter, customer.account_type, customer.customer_segment, location.city, location.region
        METRICS meter_reading.total_consumption_kwh, meter_reading.max_peak_demand_kw
    ) WHERE fiscal_year = 2026
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.total_consumption_kwh) AS cognos_total_consumption_kwh, SUM(s.total_consumption_kwh) AS semantic_total_consumption_kwh,
    IFF(ABS(COALESCE(SUM(s.total_consumption_kwh), 0) - COALESCE(SUM(c.total_consumption_kwh), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_consumption_kwh), 0)), 'PASS', 'FAIL') AS status_total_consumption_kwh,
    SUM(c.max_peak_demand_kw) AS cognos_max_peak_demand_kw, SUM(s.max_peak_demand_kw) AS semantic_max_peak_demand_kw,
    IFF(ABS(COALESCE(SUM(s.max_peak_demand_kw), 0) - COALESCE(SUM(c.max_peak_demand_kw), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.max_peak_demand_kw), 0)), 'PASS', 'EXPECTED_CHANGE (F6)') AS status_max_peak_demand_kw
FROM cognos c
FULL OUTER JOIN semantic s ON c.fiscal_year IS NOT DISTINCT FROM s.fiscal_year AND c.month_name IS NOT DISTINCT FROM s.month_name AND c.quarter IS NOT DISTINCT FROM s.quarter AND c.account_type IS NOT DISTINCT FROM s.account_type AND c.customer_segment IS NOT DISTINCT FROM s.customer_segment AND c.city IS NOT DISTINCT FROM s.city AND c.region IS NOT DISTINCT FROM s.region;
